{
  "name": "HDF5实验数据文件后端",
  "name_en": "HDF5 Experimental Data File Backend",
  "manufacturer": "",
  "description": "用于实验室测量数据存储、组织与读取的HDF5数据文件组件。它适合将实验结果按层级分组保存，记录节点属性与元数据，并存放定长、可扩展或变长数组数据，常用于实验数据归档与后处理。",
  "description_en": "A software component for storing, organizing, and reading laboratory measurement data in HDF5 files. It is used to save experimental results in hierarchical groups, record node attributes and metadata, and store fixed-size, extendable, or variable-length array data for data archiving and post-processing.",
  "tag_hints": [
    "HDF5 data storage",
    "experiment data archiving",
    "hierarchical datasets",
    "metadata attributes",
    "array data logging",
    "scientific data files"
  ],
  "actions": [
    {
      "action_name": "auto-h5file",
      "description": "获取/设置当前HDF5文件对象",
      "description_en": "Get/set the current HDF5 file object"
    },
    {
      "action_name": "auto-isopen",
      "description": "检查HDF5文件是否已打开",
      "description_en": "Check whether the HDF5 file is open"
    },
    {
      "action_name": "auto-close_file",
      "description": "刷新数据并关闭HDF5文件",
      "description_en": "Flush data and close the HDF5 file"
    },
    {
      "action_name": "auto-open_file",
      "description": "打开HDF5文件",
      "description_en": "Open an HDF5 file"
    },
    {
      "action_name": "auto-save_file_as",
      "description": "将当前HDF5文件另存为新路径",
      "description_en": "Save the current HDF5 file to a new path"
    },
    {
      "action_name": "auto-root",
      "description": "获取HDF5文件的根节点",
      "description_en": "Get the root node of the HDF5 file"
    },
    {
      "action_name": "auto-set_attr",
      "description": "设置节点属性",
      "description_en": "Set a node attribute"
    },
    {
      "action_name": "auto-has_attr",
      "description": "检查节点是否具有指定属性",
      "description_en": "Check whether a node has a specified attribute"
    },
    {
      "action_name": "auto-flush",
      "description": "将缓冲数据刷新到磁盘",
      "description_en": "Flush buffered data to disk"
    },
    {
      "action_name": "auto-define_compression",
      "description": "定义压缩方式和压缩级别",
      "description_en": "Define the compression method and compression level"
    },
    {
      "action_name": "auto-is_node_in_group",
      "description": "检查指定名称的节点是否位于某个组中",
      "description_en": "Check whether a named node is present in a group"
    },
    {
      "action_name": "auto-walk_nodes",
      "description": "遍历指定位置下的节点",
      "description_en": "Walk through nodes under a specified location"
    },
    {
      "action_name": "auto-walk_groups",
      "description": "遍历指定位置下的组",
      "description_en": "Walk through groups under a specified location"
    },
    {
      "action_name": "auto-read",
      "description": "读取数组节点中的数据",
      "description_en": "Read data from an array node"
    },
    {
      "action_name": "auto-create_carray",
      "description": "创建定长数组节点",
      "description_en": "Create a fixed-size array node"
    },
    {
      "action_name": "auto-create_earray",
      "description": "创建可扩展数组节点",
      "description_en": "Create an extendable array node"
    },
    {
      "action_name": "auto-create_vlarray",
      "description": "创建变长数组节点",
      "description_en": "Create a variable-length array node"
    },
    {
      "action_name": "auto-add_group",
      "description": "在HDF5层级中添加组节点",
      "description_en": "Add a group node to the HDF5 hierarchy"
    }
  ]
}

